// csrf.middleware.spec.ts
import { ForbiddenException } from '@nestjs/common'
import { CsrfMiddleware } from './csrf.middleware'

describe('CsrfMiddleware', () => {
    const middleware = new CsrfMiddleware()
    const next = jest.fn()

    const makeReq = (cookieToken?: string, headerToken?: string) => ({
        method: 'POST',
        cookies: cookieToken ? { 'csrf-token': cookieToken } : {},
        headers: headerToken ? { 'x-csrf-token': headerToken } : {},
    })

    it('passes when the header matches the cookie', () => {
        const req = makeReq('abc123', 'abc123')
        expect(() =>
            middleware.use(req as any, {} as any, next),
        ).not.toThrow()
    })

    it('rejects when the header does not match the cookie', () => {
        const req = makeReq('abc123', 'wrong-token')
        expect(() =>
            middleware.use(req as any, {} as any, next),
        ).toThrow(ForbiddenException)
    })

    // Every test above starts from a VALID cookie already set and only
    // varies the header value. The (cookie absent, header absent) cell —
    // exactly the shape of a forged cross-site request — is never
    // exercised by this suite, so it stayed green while the hole shipped.
})
